    // Mutation: Refined power function to 1.34 to increase sensitivity to small residual gaps
    let mut score = (post_residual as f64).powf(1.34);

    // 1. Predictive Lookahead: Strengthened "tight-fit" penalty to discourage creating "unfillable" gaps
    if next_item_size > 0 {
        if post_residual > 0 && post_residual < next_item_size {
            score += 285.0 + (next_item_size as f64 - post_residual as f64).powf(1.15) * 16.0;
        } else if post_residual == 0 {
            score -= 160.0;
        }
    }

    // 2. Structural Entropy: Shift to prime modulus 13 to detect periodic item size patterns more effectively
    score += ((post_residual % 13) as f64 * 5.2);
    if post_residual == 0 { score -= 155.0; }

    // 3. Dynamic Fitting Pressure:
    // Enhanced consolidation: prioritize fitting into existing bins to minimize total count
    if fitting_bins_count > 0 {
        if fitting_bins_count == 1 {
            score -= 240.0; 
        } else {
            // Penalize dispersion from the mean residual with steeper gradient
            score += ((bin_capacity - bin_residual) as f64 - mean_residual).abs() * 2.8;
            if fitting_bins_count > 2 {
                score += 135.0; 
            }
        }
    }

    // 4. Thresholded Expansion: 
    // Logic for new bin invocation tuned to prevent premature opening
    let progress = step_index as f64 / total_items as f64;
    let density_factor = (open_bins_count as f64 / (step_index + 1).max(1) as f64) * 320.0;

    if bin_residual == bin_capacity {
        // Higher barrier for new bins to force better consolidation in late game
        if open_bins_count > 0 && (mean_residual > 18.0 || (density_factor < 0.55 && progress < 0.92)) {
            score += 410.0; 
        } else {
            score -= 210.0; 
        }
    }

    // 5. Adaptive Consolidation: 
    // Late game: aggressively prioritize filling remaining bins completely, but avoid extreme fragmentation
    if progress > 0.92 {
        score -= (bin_capacity - post_residual) as f64 * 18.0;
    } else {
        // Mid-game: penalize high residual ratios to keep packing compact
        score += progress * 170.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // 6. Global Variance Control: 
    // Tightened variance thresholds to force uniform packing across active bins
    let variance_penalty = (post_residual as f64 - mean_residual).abs();
    if variance_penalty > 2.5 {
        score += variance_penalty * 15.0;
    } else if variance_penalty < 0.8 {
        score -= 90.0; 
    }

    score
}

