pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Start with a non-linear weight on residual space to favor tightest fits early
    let mut score = (post_residual as f64).powf(1.18);

    // 1. Predictive Lookahead: Penalize creating sub-optimal "dead-zones"
    // Refined logic: If the post_residual is smaller than the next item, we create a dead zone.
    // We scale this penalty by the inverse of the remaining stream to prevent late-game fragmentation.
    if next_item_size > 0 {
        let remaining_ratio = 1.0 - (step_index as f64 / total_items as f64);
