    // 2. Structural Entropy: Reward exact alignment and punish "fragmentation-prone" residuals
    score += ((post_residual % 13) as f64 * 3.1);
    if post_residual == 0 { score -= 45.0; }

    // 3. Dynamic Fitting Pressure: 
    // Reward bins that bring the residual closer to the global mean, reducing variance.
    if fitting_bins_count > 0 {
        if fitting_bins_count == 1 {
            score -= 92.0; 
        } else {
            let deviation = (bin_residual as f64 - post_residual as f64);
            score += deviation * 1.85;
            score += ((bin_capacity - post_residual) as f64 - mean_residual).abs() * 0.55;
        }
    }

    // 4. Thresholded Expansion: 
    // Refined heuristic for when to open a new bin.
    let density_factor = (open_bins_count as f64 / (step_index + 1).max(1) as f64) * 150.0;
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items as f64;
        // Increased threshold for opening new bins; force usage of existing bins if they are reasonably flexible.
        if open_bins_count > 0 && (mean_residual > 12.0 || (density_factor < 0.62 && progress < 0.92)) {
            score += 165.0; 
        } else {
            score -= 65.0; 
        }
    }

    // 5. Adaptive Consolidation: 
    // Shift from packing efficiency to capacity saturation as we approach the end of the stream.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.78 {
        score -= (bin_capacity - post_residual) as f64 * 2.85;
    } else {
        score += progress * 52.0 * (post_residual as f64 / bin_capacity as f64);
