pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best Fit Decreasing logic: heavily penalize larger post_residuals.
    // We want the post_residual to be as close to 0 as possible.
    score += (post_residual as f64).powf(1.5);

    // 2. Harmonic Class Penalty:
    // If the post_residual is a value that cannot fit common item sizes (e.g., < 10),
    // it creates "dead space". We penalize these small remainders.
    if post_residual < 10 && post_residual > 0 {
        score += 50.0;
    }

    // 3. Lookahead Logic:
    // If next_item_size is known, favor bins that can accommodate it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 20.0; // High reward for keeping space for the next item
        } else {
            score += 10.0; // Moderate penalty if we block the next item
        }
    }

    // 4. New Bin Threshold:
    // If this is a new bin, penalize it relative to the average state of existing bins.
    if bin_residual == bin_capacity {
        // Only open a new bin if the existing options are very poor (high post_residual).
        // Scale the penalty by the number of open bins to encourage consolidation.
        score = 45.0 + (open_bins_count as f64 * 0.5);
    } else {
        // 5. Fitting constraints:
        // If this is the only bin that fits, prioritize it strongly.
        if fitting_bins_count == 1 {
            score -= 60.0;
        }
    }

    // 6. Progress adjustment:
    // As we approach the end of the stream, prioritize tight packing (lower residuals).
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

