    }

    // Lookahead logic: If the next item fits perfectly or near-perfectly into the current post_residual,
    // prioritize this bin heavily.
    if next_item_size > 0 && next_item_size <= post_residual {
        let diff = (post_residual - next_item_size) as f64;
        // Reward placements that leave exactly enough room for the next item.
        score -= (100.0 - diff * 2.0);
    }

    // Logic for new bin candidate:
    // If bin_residual == bin_capacity, we are evaluating the cost of opening a new bin.
    if bin_residual == bin_capacity {
        // Only open a new bin if the current mean_residual is very tight (clogged bins),
        // or if we have very few open bins and want to preserve space for future large items.
        if mean_residual < 15.0 && open_bins_count > 0 {
            score += 20.0; // Discourage opening new bins if existing ones have space.
        } else {
            score -= 5.0;  // Slightly encourage fresh bins if the system is fragmented.
        }
    }

    // If this is the last fitting bin, prioritize it to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Progression awareness: As we approach the end of the stream, prioritize filling existing bins
    // to minimize total count rather than keeping bins open for future items.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize score.
    // Logic: 
    // 1. Penalize creating small, unusable gaps (Best Fit Decreasing logic).
    // 2. Reward bins that can accommodate the lookahead item (next_item_size).
    // 3. Scale behavior based on the remaining stream progression.

    let is_new_bin = bin_residual == bin_capacity;
    let progress = step_index as f64 / total_items as f64;

    // Base score is the residual space after placement. 
    // We want to minimize the post_residual to pack tightly.
    let mut score = post_residual as f64;

    // 1. Penalty for creating "dead space" (gaps < 10 are usually unusable).
    // Smaller post_residuals are generally better, but 0 is perfect.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 2. Lookahead optimization: If a bin can fit the next item, prioritize it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }

    // 3. New Bin Penalty: Discourage opening new bins unless the current options are terrible.
    if is_new_bin {
        // Only open a new bin if the mean residual is already high (bin fragmentation).
        // If fitting_bins_count is low, we are forced to open new bins sooner.
        score += 40.0 + (mean_residual * 0.5);
        if fitting_bins_count > 0 {
            score += 30.0;
        }
    }

    // 4. Global State: Adjust tightness as we approach the end of the stream.
    // Towards the end, we care less about future-proofing and more about closing bins.
    if progress > 0.8 {
        score -= (1.0 - progress) * 10.0;
    }

    // 5. Prefer bins that are already partially filled over fresh ones.
    if !is_new_bin {
        score -= (bin_capacity - bin_residual) as f64 * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;
    let cap = bin_capacity as f64;

    // Base heuristic: Minimize post_residual (Best Fit).
    // Penalize small residuals that cannot accommodate common future items (Dead Space).
    // The "tightness" of the fit is penalized if it's too small to fit the next expected item.
    let mut score = post_res;

    // Penalty for creating a bin with very little space left if the stream is early (high fragmentation risk).
    // If post_res is small but > 0, it's often better to save space for larger items later.
    if post_res > 0.0 && post_res < 15.0 {
        score += (1.0 - progress) * (20.0 - post_res);
    }

    // Reward bins that align with the mean residual of current bins to keep fragmentation uniform.
    let dev_from_mean = (post_res - mean_residual).abs();
    score += 0.5 * dev_from_mean;

    // Lookahead logic: If the next item cannot fit in the resulting post_residual, 
    // add a penalty proportional to the item size to prioritize bins that can accommodate it.
    if next_item_size > 0 && post_res < next_item_size as f64 {
        score += next_item_size as f64 * 0.8;
    }

    // If this is a new bin (bin_residual == bin_capacity), penalize opening it 
    // based on how many bins are already open and how much room is left in them.
    if bin_residual == bin_capacity {
        // Only open a new bin if the current open bins are all "bad" fits (e.g., very tight).
        // The more bins open, the more we penalize opening another one.
        score += (open_bins_count as f64 * 5.0) + (progress * 10.0);
    } else {
        // If it's an existing bin, reward it based on how many other bins can fit this item.
        // If fitting_bins_count is high, we have flexibility; don't rush to use this specific bin.
        score -= (fitting_bins_count as f64).ln();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Harmonic Penalty: Heavily penalize residuals that are small but not zero (fragmentation)
    // We favor "Perfect Fits" (post_residual == 0) or "Good Fits" (post_residual > next_item_size)
    if post_residual == 0 {
        score -= 50.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    } else if post_residual < 10 {
        score += 40.0; // Penalty for creating "slivers" that are too small for almost any item
    }

    // 2. Lookahead Coupling: If current bin fits the next item, prioritize it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 30.0;
