    // 3. Bin Stewardship: Discourage opening new bins unless necessary.
    // If this is a new bin (bin_residual == bin_capacity), add a high penalty unless it's the only option.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 100.0;
        } else {
            score -= 10.0; // Necessary evil: opening a new bin
        }
    }

    // 4. Harmonic Density Balancing: 
    // Penalize bins that deviate significantly from the mean_residual of open bins.
    // We want to keep residuals uniform to increase the probability of future fits.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.5;

    // 5. Progression Scaling: As the stream nears completion, become more aggressive with packing.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score -= (post_residual as f64) * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

