    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Reward tight packing: If the current item fits perfectly, prioritize this bin heavily.
    if post_residual == 0 {
        score -= 50.0;
    }

    // 2. Lookahead mechanism: If the post_residual is close to the next_item_size, we reward it.
    // We want to minimize the gap between the next item and the available space.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        // Reward placements that leave exactly enough space for the next item.
        score -= (100.0 - gap) * 0.5;
