    // 3. Penalty for creating "dead space": If post_residual is too small for any likely item (e.g., < 10),
    // but not zero, it's effectively wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // 4. Mean residual balancing: If this bin's post_residual is significantly better than the mean,
    // reward it to keep the average bin health high.
    if (post_residual as f64) < mean_residual {
        score -= (mean_residual - post_residual as f64) * 0.2;
    }

    // 5. New bin logic: Discourage opening a new bin unless the existing fits are poor.
    // If bin_residual == bin_capacity, we are evaluating a new bin.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Heavily penalize opening a new bin if other bins can fit the item.
            score += 60.0 + (open_bins_count as f64 * 2.0);
        } else {
            // If no other bins fit, normalize the cost of opening a new bin.
            score += 10.0;
        }
    }

    // 6. Progressive tightening: As we reach the end of the stream, prioritize closing bins.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

