    let mut score = post_residual as f64;

    // Penalty for opening a new bin prematurely
    if is_new_bin {
        // If we have fitting bins, opening a new one is generally expensive
        if fitting_bins_count > 0 {
            score += 45.0 + (progress * 20.0);
        } else {
            // No choice, must open new
            score = 0.0;
        }
    } else {
        // Penalty for creating a "sliver" (fragmentation)
        // Slivers between 1 and 8 are notoriously hard to fill
        if post_residual > 0 && post_residual < 9 {
