    let mut score = post;

    // Penalty for creating "slivers" (unusable space < 10)
    // We penalize post_residuals that are small but non-zero, as they are hard to fill.
    if post > 0.0 && post < 10.0 {
        score += 20.0 * (1.0 - (post / 10.0));
    }

    // Lookahead coupling: If next_item_size is large, avoid bins that leave small residuals
    if next_item_size > 0 {
        if post < next_item_size as f64 {
            score += 15.0 * (1.0 - progress);
