    // Dynamic thresholding for opening new bins:
    // As we approach the end of the stream (progress -> 1.0), 
    // we become more conservative about opening new bins.
    if bin_residual == bin_capacity {
        // Penalty for opening a new bin is scaled by progress
        // It becomes progressively harder to justify a new bin as the stream ends.
        score += 40.0 + (30.0 * progress);
    } else {
        // If the bin is already open, reward placements that keep the bin near the mean_residual
        // This encourages balancing residuals across bins.
        let deviation = (post - mean_residual).abs();
        score += 0.5 * deviation;
    }

    // If this is the last chance for the item, prioritize fitting it over creating a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
