        }

        // 2. Harmonic Class Optimization: Reward residuals that align with common item fractions
        // (e.g., residuals near 25, 33, 50) to facilitate future fitting.
        let rem = post_residual % 25;
        score += (rem as f64).powf(1.2);
    }

    // 3. Last Chance Logic: If this is the only bin that fits, we must take it unless 
    // the residual is extremely wasteful.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
