    }

    // 4. New Bin Thresholding: If we are considering a new bin (bin_residual == bin_capacity),
    // only choose it if the average residual is already quite low (high fragmentation).
    if bin_residual == bin_capacity {
        if open_bins_count > 0 && mean_residual > 15.0 {
