        } else {
            score -= 5.0; // Encourage new bin if existing bins are already tight
        }
    }

    // 5. Dynamic Progress Multiplier: As the stream nears the end, prioritize tight packing
    // to avoid leaving trailing items that force new bins.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
