    let is_new_bin = bin_residual == bin_capacity;

    // Base score: We prefer the smallest remaining space (Best Fit)
    let mut score = post_residual as f64;

    // Penalty for opening a new bin if other options exist
    if is_new_bin {
        if fitting_bins_count > 0 {
            score += 45.0 + (progress * 20.0);
        } else {
            score -= 10.0;
        }
    } else {
        // Reward bins that are "almost full" after placement to minimize fragmentation
        if post_residual < 10 {
            score -= 15.0;
        }

        // Lookahead heuristic: If the next item fits in this post_residual, prioritize this bin
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 25.0;
        }

        // Global state awareness: If we have many open bins, penalize ones that leave "awkward" gaps
        // An awkward gap is defined as a residual smaller than the smallest likely item (e.g., < 10) 
        // but larger than 0.
        if post_residual > 0 && post_residual < 10 {
            score += 12.0;
        }
    }

    // Dynamic balancing: As we approach the end of the stream, prioritize closing bins
    // by being more aggressive with Best Fit (penalizing larger post_residuals)
    if progress > 0.8 {
        score += (post_residual as f64) * 0.5;
    }

    // Encourage density: penalize bins that deviate significantly from the current mean residual
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Core objective: Minimize post_residual, but prioritize filling bins to 0.
    // Enhanced weight on exact fits to reduce fragmentation.
    let mut score = (post_residual as f64).powf(1.18);

    // 1. Predictive Lookahead: Refined penalty for creating "orphaned" space.
    // If post_residual is too small to accommodate the next item, penalize proportionally.
    if next_item_size > 0 {
        if post_residual > 0 && post_residual < next_item_size {
            score += 162.0 + (next_item_size as f64 - post_residual as f64) * 7.2;
        } else if post_residual == 0 {
            score -= 42.0; 
        }
    }

    // 2. Structural Entropy: Harmonic alignment.
    // Reward packing that leaves residuals that are multiples of 8, as they are more versatile for standard items.
    score += (post_residual % 8) as f64 * 3.1;
    if post_residual == 0 { score -= 68.0; }

    // 3. Dynamic Fitting Pressure: 
    // Reward bins that keep us close to the global mean, but favor deep packing.
    if fitting_bins_count > 0 {
        if fitting_bins_count == 1 {
            score -= 110.0; 
        } else {
            let usage = (bin_capacity - bin_residual) as f64;
            score += (usage - mean_residual).abs() * 0.82;
            // Penalize high usage bins if they are already near capacity to force overflow into new bins.
            if bin_residual < 15 { score += 45.0; }
        }
    }

    // 4. Thresholded Expansion: 
    // Heuristic for opening a new bin vs reusing existing ones.
    let progress = step_index as f64 / total_items as f64;
    let density_factor = (open_bins_count as f64 / (step_index + 1).max(1) as f64) * 172.0;

    if bin_residual == bin_capacity {
        // Tighten criteria for new bins: only open if existing bins are heavily fragmented (mean_residual > 12).
        if open_bins_count > 0 && (mean_residual > 12.0 || (density_factor < 0.65 && progress < 0.94)) {
            score += 195.0; 
        } else {
            score -= 88.0; 
        }
    }

    // 5. Adaptive Consolidation: 
    // Late-game: aggressively close bins by penalizing residuals more heavily as we approach the end.
    if progress > 0.90 {
        score -= (bin_capacity - post_residual) as f64 * 5.1;
    } else {
        // Mid-game: prevent wide-spread fragmentation.
        score += progress * 72.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // 6. Global Variance Control: 
    // Penalize extreme residual outliers to maintain a uniform bin state.
    let variance_penalty = (post_residual as f64 - mean_residual).abs();
    if variance_penalty > 8.0 {
        score += variance_penalty * 4.8;
    }

    score
