    };

    // Reward bins that maintain a residual close to the average of existing bins,
    // which helps prevent fragmentation (clustering).
    let deviation_penalty = (post - mean_residual).abs() * 0.5;

    // Lookahead logic: if the next item is large, prioritize keeping larger residuals.
