    } else {
        0.0
    };

    // New bin aversion: If we have fitting bins, heavily penalize opening a new bin (where bin_residual == bin_capacity).
    // The penalty increases as the stream progresses to force consolidation.
    let new_bin_penalty = if bin_residual == bin_capacity && fitting_bins_count > 0 {
