    let mut score = post + dead_space_penalty + deviation_penalty + lookahead_penalty + new_bin_penalty;

    // Favor bins that result in a post_residual that is a multiple of common item sizes (heuristic optimization).
    if post > 0.0 && (post % 10.0 == 0.0) {
        score -= 5.0;
    }

    score
}

