    let mut score = (post_residual as f64).powf(1.38);

    // 1. Predictive Lookahead: Refined to identify "tight-fit" opportunities.
    // If post_residual is just below next_item_size, we treat it as a high-cost failure.
    if next_item_size > 0 {
        if post_residual > 0 && post_residual < next_item_size {
            score += 310.0 + (next_item_size as f64 - post_residual as f64).powf(1.2) * 18.0;
        } else if post_residual == 0 {
            score -= 180.0; // Stronger reward for perfect closure
        }
    }

    // 2. Structural Entropy: Shift to modulus 17 to capture wider range of item patterns.
    score += ((post_residual % 17) as f64 * 6.0);
    if post_residual == 0 { score -= 170.0; }

    // 3. Dynamic Fitting Pressure:
    // Aggressive consolidation: prioritize existing bins to minimize total count.
    if fitting_bins_count > 0 {
        if fitting_bins_count == 1 {
            score -= 280.0; 
        } else {
            // Penalize dispersion from the mean residual with steeper gradient to force uniformity.
            score += ((bin_capacity - bin_residual) as f64 - mean_residual).abs() * 3.5;
            if fitting_bins_count > 2 {
                score += 150.0; 
            }
        }
    }

    // 4. Thresholded Expansion: 
    // Logic for new bin invocation tuned to prevent premature opening.
    let progress = step_index as f64 / total_items as f64;
    let density_factor = (open_bins_count as f64 / (step_index + 1).max(1) as f64) * 350.0;

    if bin_residual == bin_capacity {
        // Higher barrier for new bins to force better consolidation in late game.
        if open_bins_count > 0 && (mean_residual > 15.0 || (density_factor < 0.45 && progress < 0.90)) {
            score += 480.0; 
        } else {
            score -= 250.0; 
        }
    }

    // 5. Adaptive Consolidation: 
    // Late game: aggressively prioritize filling remaining bins completely.
    if progress > 0.90 {
        score -= (bin_capacity - post_residual) as f64 * 22.0;
    } else {
        // Mid-game: penalize high residual ratios to keep packing compact.
        score += progress * 190.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // 6. Global Variance Control: 
    // Tightened variance thresholds to force uniform packing across active bins.
    let variance_penalty = (post_residual as f64 - mean_residual).abs();
    if variance_penalty > 2.0 {
        score += variance_penalty * 18.0;
    } else if variance_penalty < 0.5 {
        score -= 110.0; 
    }

    score
}

