    // We favor bins that become nearly full (post_residual -> 0).
    score += post_residual as f64 * 1.5;

    // 2. Harmonic Class Logic: Reward placements that create "clean" residuals
    // Multiples of 20 or 25 are often easier to fill later.
    if post_residual % 20 == 0 {
        score -= 15.0;
    } else if post_residual % 10 == 0 {
        score -= 5.0;
    }

    // 3. Lookahead Synergy: If the next item fits into the current post_residual,
    // give a massive priority boost to this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 45.0;
        // Further refine: reward bins that leave minimal space after the NEXT item too.
        let post_post = (post_residual - next_item_size) as f64;
        score += post_post * 0.5;
    }

    // 4. Scarcity/Bottleneck Logic:
    // If this is the ONLY bin that can fit the item, we are forced to use it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 100.0;
    }

    // 5. Empty Bin Threshold:
    // Only open a new bin if the current mean_residual is very small,
    // indicating that current bins are already highly fragmented.
    if bin_residual == bin_capacity {
        if open_bins_count > 0 && mean_residual > 25.0 {
            score += 50.0; // Heavily penalize opening new bins if existing are empty enough
        } else {
            score += 30.0; // Baseline penalty for opening a new bin
        }
    }

    // 6. Progressive packing:
    // As the stream nears the end, prioritize closing bins (lower residual) over new bins.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 20.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Mutation: Increased power sensitivity to 1.42 to favor near-perfect fits more aggressively
    let mut score = (post_residual as f64).powf(1.42);

    // 1. Predictive Lookahead: Refined penalty for blocking future moves
    if next_item_size > 0 {
        if post_residual > 0 && post_residual < next_item_size {
            // Increased penalty for creating unreachable gaps relative to average item size
            score += 315.0 + (next_item_size as f64 - post_residual as f64).powf(1.22) * 18.0;
        } else if post_residual == 0 {
            score -= 195.0; // Stronger reward for clearing bins
        }
    }

    // 2. Structural Entropy: Shift to prime 17 to better handle typical bin sizes (e.g., 100)
    score += ((post_residual % 17) as f64 * 4.8);
    if post_residual == 0 { score -= 175.0; }

    // 3. Dynamic Fitting Pressure:
    if fitting_bins_count > 0 {
        if fitting_bins_count == 1 {
            score -= 280.0; 
        } else {
            // Narrowed corridor for mean residual adherence
            score += ((bin_capacity - bin_residual) as f64 - mean_residual).abs() * 3.4;
            if fitting_bins_count > 2 {
                score += 155.0; 
            }
        }
    }

    // 4. Thresholded Expansion: 
    let progress = step_index as f64 / total_items as f64;
    let density_factor = (open_bins_count as f64 / (step_index + 1).max(1) as f64) * 350.0;

    if bin_residual == bin_capacity {
        // Adjusted logic: higher penalty for new bins when existing ones are near-empty
        if open_bins_count > 0 && (mean_residual > 22.0 || (density_factor < 0.65 && progress < 0.95)) {
            score += 480.0; 
        } else {
            score -= 240.0; 
        }
    }

    // 5. Adaptive Consolidation: 
    // Late game: aggressively prioritize filling remaining bins completely
    if progress > 0.90 {
        score -= (bin_capacity - post_residual) as f64 * 22.0;
    } else {
        // Mid-game: penalize high residual ratios to keep packing compact
        score += progress * 190.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // 6. Global Variance Control: 
    // Tightened variance thresholds to force uniform packing across active bins
    let variance_penalty = (post_residual as f64 - mean_residual).abs();
    if variance_penalty > 2.0 {
        score += variance_penalty * 18.0;
    } else if variance_penalty < 0.5 {
        score -= 110.0; 
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead space penalty: If post_residual is in the range [1, 9], it is highly likely to be 
    // unusable for future items (min item size is 10). Penalize heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 100.0 - (post_residual as f64 * 10.0);
    }

    // 2. Lookahead optimization: If the next item cannot fit into the post_residual,
    // we prioritize bins that leave enough space for the next item if possible.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 50.0;
    }

    // 3. Open bins pressure: If this is a new bin (bin_residual == bin_capacity), 
    // penalize opening it based on the number of bins already open to discourage fragmentation.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64 * 15.0);
    } else {
        // 4. Tightness reward: Favor bins that are already "fuller" (lower mean_residual)
        // to consolidate space.
        score -= (100.0 - mean_residual) * 0.5;
    }

    // 5. Last chance mitigation: If this is the only bin that fits, reduce the penalty 
    // to ensure the item is placed rather than forcing a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    score
}

